export { MAX_PROTOTYPE_SRCDOC_BYTES, renderPrototypeSlot }

const DIFF_LABELS = { added: '新增', modified: '修改', removed: '拟移除', impacted: '受波及' }
const VERDICT_LABELS = {
  SYNCED: '已同步',
  CHANGED: '有变更',
  DRAFT: '草稿',
  CONFIRMED: '已确认',
  STALE: '待重审',
}

function localizeVerdictStatus(raw) {
  const key = String(raw || 'SYNCED').trim()
  return VERDICT_LABELS[key.toUpperCase()] || key
}

export function buildGeneratedHeaderLine({ mode = 'architecture-map', featureMapSha256 = '' } = {}) {
  const kind = mode === 'visual-brief' ? 'visual-brief' : 'architecture-map'
  const sha = /^[0-9a-f]{64}$/i.test(String(featureMapSha256 || ''))
    ? String(featureMapSha256).toLowerCase()
    : sha256Text(String(featureMapSha256 || ''))
  return `<!-- @generated by project-forge ${kind}; DO NOT EDIT — schema=v2 feature-map-sha256=${sha} -->`
}

function renderZoomFloatHtml(vpId) {
  return `<div class="pf-zoom-float"><button class="pf-btn pf-btn-sm" type="button" data-zoom-action="out" data-zoom-target="${vpId}" aria-label="缩小">-</button><button class="pf-btn pf-btn-sm pf-zoom-readout" type="button" data-zoom-action="reset" data-zoom-target="${vpId}" data-zoom-label>100%</button><button class="pf-btn pf-btn-sm" type="button" data-zoom-action="in" data-zoom-target="${vpId}" aria-label="放大">+</button><button class="pf-btn pf-btn-sm" type="button" data-zoom-action="fit" data-zoom-target="${vpId}">适配</button></div>`
}

function renderFocusBarHtml(tree, hasActiveDiff) {
  const domBtns = (tree.domains || []).map((d) => {
    const color = escapeXml(d.palette?.stroke || '#1b5e6b')
    return `<button type="button" class="pf-seg-btn" data-domain-filter="${escapeHtml(d.id)}"><span class="pf-dot" style="background:${color}"></span>${escapeHtml(d.shortTitle)}</button>`
  }).join('')
  const diffBtn = `<button id="btn-only-diff" type="button" class="pf-seg-btn"${hasActiveDiff ? '' : ' disabled title="当前无活跃变更"'}>仅看本次变更</button>`
  return `<div id="pf-focus-bar" class="pf-focus-bar"><div class="pf-seg"><button type="button" class="pf-seg-btn is-active" data-domain-filter="">全部域</button>${domBtns}</div>${diffBtn}</div>`
}

function renderDomainTreeSvg(tree) {
  const domainGroupXml = tree.domains.map((dom) => {
    const stroke = escapeXml(dom.palette.stroke)
    const fill = escapeXml(dom.palette.fill)
    const descXml = dom.shortDescription
      ? `<text x="${dom.x + 28}" y="${dom.y + 46}" class="pf-domain-desc">${escapeXml(dom.shortDescription)}</text>`
      : ''
    return [
      `<g class="pf-domain-box" data-domain-id="${escapeXml(dom.id)}">`,
      `<rect x="${dom.x}" y="${dom.y}" width="${dom.w}" height="${dom.h}" rx="12" fill="${fill}" stroke="${stroke}" stroke-opacity="0.32" stroke-width="1" />`,
      `<circle cx="${dom.x + 18}" cy="${dom.y + 24}" r="4" fill="${stroke}" />`,
      `<text x="${dom.x + 28}" y="${dom.y + 28}" class="pf-domain-title">${escapeXml(dom.shortTitle)}</text>`,
      `<text x="${dom.x + dom.w - 16}" y="${dom.y + 28}" text-anchor="end" class="pf-domain-meta">${dom.featureCount} 个模块</text>`,
      descXml,
      `</g>`,
    ].join('')
  }).join('\n')

  const edgeXml = tree.edges.map((edge) => {
    const st = edge.edgeState || (edge.impacted ? 'impacted' : 'context')
    const cls = st !== 'context' ? `pf-edge pf-edge-${escapeXml(st)}` : 'pf-edge'
    return `<path class="${cls}" data-edge-id="${escapeXml(edge.id)}" data-from-id="${escapeXml(edge.fromId)}" data-to-id="${escapeXml(edge.toId)}" d="${escapeXml(edge.pathD)}" marker-end="url(#pf-arrow)" />`
  }).join('\n')

  const nodeXml = tree.nodes.map((node) => {
    const diffText = DIFF_LABELS[node.diffState] || ''
    const diffBadge = diffText
      ? `<rect x="${node.x + 14}" y="${node.y + 11}" width="52" height="18" rx="9" class="pf-badge-${escapeXml(node.diffState)}" /><text x="${node.x + 40}" y="${node.y + 23}" text-anchor="middle" class="pf-badge-text">${escapeXml(diffText)}</text>`
      : ''
    const rightTag = node.risk === 'high'
      ? `<text x="${node.x + node.w - 14}" y="${node.y + 23}" text-anchor="end" class="pf-risk-high">高风险</text>`
      : (node.isVirtual ? `<text x="${node.x + node.w - 14}" y="${node.y + 23}" text-anchor="end" class="pf-node-meta">规划态</text>` : '')
    const roleSummary = node.shortSummary || truncateLabel(node.description || toRelPath(node.primaryAnchor) || node.id, 38)
    const titleCls = node.diffState === 'removed' ? 'pf-node-title pf-node-title-removed' : 'pf-node-title'
    const statsText = node.isVirtual
      ? (node.diffState === 'removed' ? '拟移除 · 待清理' : '规划新增 · 虚拟节点')
      : `${node.modules.length} 模块 · ${node.tests.length} 测试`
    return [
      `<g class="pf-node pf-diff-${escapeXml(node.diffState)}" tabindex="0" role="button" data-node-id="${escapeXml(node.id)}" data-node-label="${escapeXml(node.title)}" data-domain-id="${escapeXml(node.domain)}" data-diff-state="${escapeXml(node.diffState)}">`,
      `<rect x="${node.x}" y="${node.y}" width="${node.w}" height="${node.h}" rx="10" class="pf-node-card" />`,
      diffBadge,
      rightTag,
      `<text x="${node.x + 14}" y="${node.y + 48}" class="${titleCls}">${escapeXml(node.shortTitle)}</text>`,
      `<text x="${node.x + 14}" y="${node.y + 70}" class="pf-node-sub">${escapeXml(roleSummary)}</text>`,
      `<text x="${node.x + 14}" y="${node.y + 96}" class="pf-node-stats">${escapeXml(statsText)}</text>`,
      `</g>`,
    ].join('')
  }).join('\n')

  return [
    `<svg id="svg-tree" class="pf-svg" viewBox="0 0 ${tree.width} ${tree.height}" width="${tree.width}" height="${tree.height}" role="img" aria-label="领域与功能架构全景图">`,
    `<defs><marker id="pf-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 1 L 10 5 L 0 9 z" fill="currentColor" /></marker></defs>`,
    `<g class="pf-zoom-layer">`,
    domainGroupXml,
    edgeXml,
    nodeXml,
    `</g>`,
    `</svg>`,
  ].join('\n')
}

function renderFlowDagSvg(flow) {
  const laneXml = flow.lanes.map((lane) => {
    const stroke = escapeXml(lane.palette.stroke)
    const fill = escapeXml(lane.palette.fill)
    return [
      `<g class="pf-lane" data-lane-id="${escapeXml(lane.id)}">`,
      `<rect x="${lane.x}" y="${lane.y}" width="${lane.w}" height="${lane.h}" rx="8" fill="${fill}" stroke="${stroke}" stroke-opacity="0.24" stroke-width="1" />`,
      `<rect x="${lane.x}" y="${lane.y}" width="${lane.labelW}" height="${lane.h}" rx="8" fill="${fill}" stroke="${stroke}" stroke-opacity="0.32" stroke-width="1" />`,
      `<circle cx="${lane.x + 16}" cy="${lane.y + lane.h / 2}" r="3.5" fill="${stroke}" />`,
      `<text x="${lane.x + 26}" y="${lane.y + lane.h / 2 + 4}" class="pf-lane-label">${escapeXml(lane.shortTitle)}</text>`,
      `</g>`,
    ].join('')
  }).join('\n')

  const edgeXml = flow.edges.map((edge) => {
    const st = edge.edgeState || (edge.impacted ? 'impacted' : 'context')
    const cls = st !== 'context' ? `pf-edge pf-edge-${escapeXml(st)}` : 'pf-edge'
    return `<path class="${cls}" data-edge-id="${escapeXml(edge.id)}" data-from-id="${escapeXml(edge.fromId)}" data-to-id="${escapeXml(edge.toId)}" d="${escapeXml(edge.pathD)}" marker-end="url(#pf-flow-arrow)" />`
  }).join('\n')

  const nodeXml = flow.nodes.map((node) => {
    const diffText = DIFF_LABELS[node.diffState] || ''
    const stageLine = diffText ? `阶段 ${node.rank + 1} · ${diffText}` : `阶段 ${node.rank + 1}`
    return [
      `<g class="pf-node pf-diff-${escapeXml(node.diffState)}" tabindex="0" role="button" data-node-id="${escapeXml(node.id)}" data-node-label="${escapeXml(node.title)}" data-diff-state="${escapeXml(node.diffState)}">`,
      `<rect x="${node.x}" y="${node.y}" width="${node.w}" height="${node.h}" rx="8" class="pf-node-card" />`,
      `<text x="${node.x + 12}" y="${node.y + 28}" class="pf-node-title">${escapeXml(node.shortTitle)}</text>`,
      `<text x="${node.x + 12}" y="${node.y + 50}" class="pf-node-stats">${escapeXml(stageLine)}</text>`,
      `</g>`,
    ].join('')
  }).join('\n')

  return [
    `<svg id="svg-flow" class="pf-svg" viewBox="0 0 ${flow.width} ${flow.height}" width="${flow.width}" height="${flow.height}" role="img" aria-label="跨功能角色泳道流转图">`,
    `<defs><marker id="pf-flow-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 1 L 10 5 L 0 9 z" fill="currentColor" /></marker></defs>`,
    `<g class="pf-zoom-layer">`,
    laneXml,
    edgeXml,
    nodeXml,
    `</g>`,
    `</svg>`,
  ].join('\n')
}

function renderFlowBarHtml(flows = []) {
  if (!Array.isArray(flows) || flows.length === 0) return ''
  const flowBtns = flows.map((f, idx) => `<button type="button" class="pf-seg-btn${idx === 0 ? ' is-active' : ''}" data-flow-select="${escapeHtml(f.id)}">${escapeHtml(f.title)}</button>`).join('')
  const allBtn = '<button type="button" class="pf-seg-btn" data-flow-select="">全部泳道总图</button>'
  return `<div id="pf-flow-bar" class="pf-flow-bar"><span class="pf-inspector-label">主流程：</span><div class="pf-seg">${flowBtns}${allBtn}</div></div><div id="pf-flow-ribbon" class="pf-flow-ribbon" hidden></div>`
}

export function renderVisualHtml({ visualModel, featureMapSha256 = '', mode = 'architecture-map' } = {}) {
  const model = visualModel || {}
  const resolvedMode = mode === 'visual-brief' || model.mode === 'visual-brief' ? 'visual-brief' : 'architecture-map'
  const isBrief = resolvedMode === 'visual-brief'
  const headerLine = buildGeneratedHeaderLine({ mode: resolvedMode, featureMapSha256 })
  const title = escapeHtml(model.title || (isBrief ? '实时规划简报' : '架构全景图'))
  const verdict = model.verdict || { status: '已同步', tone: 'pass', summary: '' }
  const verdictLabel = escapeHtml(localizeVerdictStatus(verdict.status || '已同步'))
  const tree = model.tree || { width: 640, height: 360, domains: [], nodes: [], edges: [] }
  const flow = model.flow || { width: 640, height: 280, lanes: [], nodes: [], edges: [], flows: [] }
  const flowsList = Array.isArray(flow.flows) ? flow.flows : []
  const prototypes = Array.isArray(model.prototypes) ? model.prototypes : []
  const showDiffTab = !isBrief && Boolean(model.hasActiveDiff)
  const showProtoTab = prototypes.length > 0 || isBrief
  const defaultTab = isBrief ? 'brief' : 'tree'
  const defaultFollowup = isBrief ? '变更蓝图' : '全景架构'

  const compactClientModel = {
    mode: resolvedMode,
    title: model.title || (isBrief ? '实时规划简报' : '架构全景图'),
    tree: {
      nodes: tree.nodes.map((n) => ({
        id: n.id,
        title: n.title,
        domain: n.domain,
        domainTitle: n.domainTitle || n.domain,
        diffState: n.diffState,
        isVirtual: Boolean(n.isVirtual),
        changeDetail: n.changeDetail || null,
        impactReasons: n.impactReasons || [],
        risk: n.risk,
        description: n.description || '',
        cx: n.cx,
        cy: n.cy,
        entrypoints: (n.entrypoints || []).slice(0, 3),
        modules: (n.modules || []).slice(0, 12),
        tests: (n.tests || []).slice(0, 8),
        verifyTools: (n.verifyTools || []).slice(0, 6),
        docAnchors: (n.docAnchors || []).slice(0, 6),
      })),
      edges: tree.edges.map((e) => ({ fromId: e.fromId, toId: e.toId })),
    },
    flow: {
      flows: flowsList.map((fl) => ({
        id: fl.id,
        title: fl.title,
        featureIds: fl.featureIds || [],
        steps: fl.steps || [],
      })),
    },
    walkthrough: (model.walkthrough || []).map((w) => ({
      targetId: w.targetId,
      title: w.title,
      detail: w.detail,
    })),
  }

  const tabsHtml = [
    isBrief ? '<button class="pf-tab is-active" type="button" data-tab-target="brief">变更蓝图</button>' : '',
    `<button class="pf-tab${defaultTab === 'tree' ? ' is-active' : ''}" type="button" data-tab-target="tree">全景架构</button>`,
    '<button class="pf-tab" type="button" data-tab-target="flow">业务流转</button>',
    showDiffTab ? '<button class="pf-tab" type="button" data-tab-target="diff">变更影响</button>' : '',
    showProtoTab ? '<button class="pf-tab" type="button" data-tab-target="prototypes">方案原型</button>' : '',
  ].filter(Boolean).join('')

  const html = [
    headerLine,
    '<!DOCTYPE html>',
    '<html lang="zh-CN" data-theme="auto">',
    '<head>',
    '<meta charset="utf-8" />',
    '<meta name="viewport" content="width=device-width, initial-scale=1" />',
    `<title>${title}</title>`,
    `<style>${buildStylesCss({ isBrief })}</style>`,
    '</head>',
    '<body>',
    '<main class="pf-shell">',
    '<header class="pf-topbar">',
    `<div class="pf-top-left"><h1 class="pf-title">${title}</h1><span class="pf-verdict-pill" data-tone="${escapeHtml(verdict.tone || 'pass')}">${verdictLabel}</span><nav class="pf-tabs" aria-label="视图切换">${tabsHtml}</nav></div>`,
    `<div class="pf-controls"><input id="pf-search" class="pf-search" type="search" placeholder="搜索模块、域或路径..." aria-label="搜索模块、域或路径" /><button id="btn-walk-start" class="pf-btn" type="button">分步导览</button><button id="btn-theme" class="pf-btn" type="button">主题：跟随系统</button><button id="btn-followup-ctx" class="pf-btn pf-btn-primary" type="button" data-followup-panel="${defaultFollowup}">复制追问</button></div>`,
    '</header>',
    '<section class="pf-workspace">',
    '<div>',
    isBrief ? `<article class="pf-panel" data-tab-panel="brief">${renderBlueprintLandingHtml(model, verdict, verdictLabel)}</article>` : '',
    `<article class="pf-panel" data-tab-panel="tree"${defaultTab === 'tree' ? '' : ' hidden'}>${renderFocusBarHtml(tree, Boolean(model.hasActiveDiff))}<div class="pf-canvas-wrap"><div id="vp-tree" class="pf-viewport">\n${renderDomainTreeSvg(tree)}\n</div>${renderZoomFloatHtml('vp-tree')}</div></article>`,
    `<article class="pf-panel" data-tab-panel="flow" hidden>${renderFlowBarHtml(flowsList)}<div class="pf-canvas-wrap"><div id="vp-flow" class="pf-viewport">\n${renderFlowDagSvg(flow)}\n</div>${renderZoomFloatHtml('vp-flow')}</div></article>`,
    showDiffTab ? `<article class="pf-panel" data-tab-panel="diff" hidden><div class="pf-scroll-panel"><div class="pf-chg-grid">${renderDiffRowsHtml(tree.nodes)}</div></div></article>` : '',
    showProtoTab ? `<article class="pf-panel" data-tab-panel="prototypes" hidden><div class="pf-panel-head"><h2 class="pf-panel-title">方案原型对比</h2><div class="pf-controls">${renderPrototypeSwitcher(prototypes)}</div></div><div id="pf-proto-grid" class="pf-proto-grid">${renderPrototypeSlot(prototypes)}</div></article>` : '',
    '</div>',
    '<aside class="pf-sidebar pf-panel">',
    `<div id="pf-dir-view" class="pf-side-view"><div class="pf-panel-head"><h2 class="pf-panel-title">模块目录</h2><span class="pf-stats-inline">${tree.domains.length} 域 · ${tree.nodes.length} 模块</span></div><div class="pf-catalog">${renderCatalogHtml(tree)}</div></div>`,
    renderInspectorShellHtml(),
    '</aside>',
    '</section>',
    '</main>',
    renderDialogsHtml(),
    `<script id="pf-visual-data" type="application/json">${escapeJsonForScript(compactClientModel)}</script>`,
    `<script>\n${buildClientScript()}\n</script>`,
    '</body>',
    '</html>',
    '',
  ].filter((x) => x !== '').join('\n')

  return {
    html,
    bytes: Buffer.byteLength(html, 'utf8'),
    sha256: sha256Text(html),
    headerLine,
  }
}
